const _lastIdx = {};
function pickLine(pool){ const arr = LINES[pool] || LINES.happy; if(arr.length===1) return arr[0];
  let i; do { i = Math.floor(Math.random()*arr.length); } while(i === _lastIdx[pool]); _lastIdx[pool] = i;
  return arr[i].replace('{c}', coachName()); }
const BOJI_CANDIDATE = 'assets/boji-companion-candidate.png';
const BOJI_PET_CANDIDATE = 'assets/boji-companion-pet-candidate.png';
const PET_THEME = { eyeLine:'#332c29', eyeC:'#245d4b', gold:'#efb44e', blush:'#dc8390', trimB:'#397360', skinA:'#fff5e8' };
const PET_FACE = {
  happy:{eye:'open',mouth:'smile',blush:1}, cheer:{eye:'smile',mouth:'grin',blush:1},
  proud:{eye:'open',mouth:'smile',blush:1}, expect:{eye:'open',mouth:'small',blush:1},
  think:{eye:'open',mouth:'small',blush:0}, sad:{eye:'open',mouth:'wave',blush:0},
  sleep:{eye:'closed',mouth:'small',blush:0}, wave:{eye:'smile',mouth:'grin',blush:1},
  hover:{eye:'open',mouth:'o',blush:1}, drag:{eye:'open',mouth:'o',blush:1},
  blink:{eye:'closed',mouth:'smile',blush:1}
};
function petEye(kind,cx,side){
  const left=cx-9,right=cx+9,y=63,ink=PET_THEME.eyeLine;
  if(kind==='closed'||kind==='smile') return '<path d="M'+left+' '+y+' Q'+cx+' '+(y+6)+' '+right+' '+y+'" stroke="'+ink+'" stroke-width="2.8" fill="none" stroke-linecap="round"/>';
  return '<g><ellipse cx="'+cx+'" cy="'+y+'" rx="7.4" ry="9" fill="#fff"/><ellipse cx="'+cx+'" cy="'+(y+1)+'" rx="5.6" ry="7.2" fill="#397c61"/><ellipse cx="'+cx+'" cy="'+(y+2)+'" rx="2.5" ry="4.2" fill="'+PET_THEME.eyeC+'"/><circle cx="'+(cx-2)+'" cy="'+(y-2)+'" r="2.1" fill="#fff"/></g>';
}
function petMouth(kind){
  if(kind==='o') return '<ellipse cx="60" cy="78" rx="3.5" ry="4.2" fill="#a9505b"/>';
  if(kind==='small') return '<path d="M58 78 Q60 80 62 78" stroke="#a9505b" stroke-width="1.8" fill="none" stroke-linecap="round"/>';
  if(kind==='wave') return '<path d="M55 78 Q58 75 60 78 Q62 81 65 78" stroke="#a9505b" stroke-width="1.8" fill="none" stroke-linecap="round"/>';
  return '<path d="M54 76 Q60 83 66 76" stroke="#a9505b" stroke-width="2" fill="none" stroke-linecap="round"/>';
}const PET_SKINS = [
  { key:'boji', name:'Boji', asset:BOJI_PET_CANDIDATE, render:()=>'' },
  { key:'photo', name:'照片桌宠', render:m=>photoPetSVG(m, (STATE.settings && STATE.settings.petPhoto) || ''), photo:true }
];
function skinBy(key){ return PET_SKINS.find(row=>row.key===key) || PET_SKINS[0]; }
function petSVG(mood){
  if(STATE.petSkin==='photo') return photoPetSVG(mood, (STATE.settings && STATE.settings.petPhoto) || '');
  return '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 120 150" width="240" height="300"><image href="'+BOJI_PET_CANDIDATE+'" width="120" height="150" preserveAspectRatio="xMidYMid meet"/></svg>';
}
function petArtURI(mood){
  if(skinBy(STATE.petSkin).photo) return 'data:image/svg+xml;charset=utf-8,'+encodeURIComponent(petSVG(mood));
  return BOJI_PET_CANDIDATE;
}
function applyPetArt(mood){
  const img=document.getElementById('pet-img');if(!img)return;
  const skin=skinBy(STATE.petSkin),pet=document.getElementById('pet');
  if(pet){pet.classList.remove('pet-video');pet.classList.toggle('skin-photo',skin.key==='photo');pet.classList.toggle('skin-boji',skin.key==='boji');}
  img.src=skin.asset&&!skin.photo?skin.asset:petArtURI(mood||STATE.petMood||'happy');
}
let blinkTimer=null;
function prefersReducedMotion(){
  try{return !!(window.matchMedia&&window.matchMedia('(prefers-reduced-motion: reduce)').matches);}catch(_){return false;}
}
function scheduleBlink(){
  clearTimeout(blinkTimer);
  blinkTimer=null;
  if(document.hidden||prefersReducedMotion())return;
  blinkTimer=setTimeout(()=>{
    const pet=document.getElementById('pet');
    if(pet&&!document.hidden&&!prefersReducedMotion()){
      pet.classList.add('boji-blink');
      setTimeout(()=>pet.classList.remove('boji-blink'),150);
    }
    scheduleBlink();
  },3700+Math.random()*3300);
}let petTimer=null, idleTimer=null, sleepTimer=null, nudgeTimer=null;
function setMood(mood, autoRevertMs){
  const pet = $('#pet'); if(!pet) return;
  Array.from(pet.classList).forEach(c=>{ if(c.startsWith('mood-')) pet.classList.remove(c); });
  pet.classList.add('mood-' + mood);
  applyPetArt(mood);
  say(pickLine(mood));
  STATE.petMood = mood; save();
  clearTimeout(petTimer);
  if(autoRevertMs) petTimer = setTimeout(()=>setMood('happy'), autoRevertMs);
}
// 气泡打字机：逐字显示，读完停留后消失；多句排队不丢字
let bubbleQueue = [], bubbleBusy = false;
function say(text){
  if(!text) return;
  bubbleQueue.push(text); pumpBubble();
  // 语音朗读：仅在设置开启 + 处于桌宠主界面时才发声（不支持 / 不在主界面则静默）
  if(STATE.settings && STATE.settings.petVoice) petSpeak(text, { mood: STATE.petMood });
}
function pumpBubble(){ if(bubbleBusy) return; const t = bubbleQueue.shift(); if(t==null) return; bubbleBusy = true; typeBubble(t, ()=>{ bubbleBusy = false; pumpBubble(); }); }
function typeBubble(text, done){
  const b = $('#pet-bubble'); if(!b){ done(); return; }
  b.classList.remove('round');            // 让位于台词气泡（圆气泡与打字机共用同一元素）
  b.classList.add('show'); b.textContent = ''; clearTimeout(b._t);
  let i = 0;
  const tick = () => { if(i <= text.length){ b.textContent = text.slice(0, i); i++; b._t = setTimeout(tick, TYPE.charMs); }
    else { const dwell = Math.min(TYPE.maxDwell, Math.max(TYPE.minDwell, text.length * TYPE.dwellPerChar));
      b._t = setTimeout(()=>{ b.classList.remove('show'); b._t = setTimeout(done, 360); }, dwell); } };
  b._t = setTimeout(tick, TYPE.startDelay);
}
function petIdle(){
  clearTimeout(idleTimer);
  idleTimer=null;
  if(document.hidden||prefersReducedMotion())return;
  idleTimer = setTimeout(()=>{
    idleTimer=null;
    if(document.hidden||prefersReducedMotion())return;
    const r = Math.random();
    // 动作优先（v1.1）：溜达权重最高，符合「动作 > 表情」的取向
    if(r<0.26) petWalk();                                    // ① 沿边溜达（Shimeji walk）
    else if(r<0.34) petFlip();                               // 随机翻个跟头（视频同款小把戏）
    else if(r<0.42) petAct('crouch');                        // ④ 蜷缩：视觉高度腰斩（视频 5.5–7.1s）
    else if(r<0.48) petDashGhost();                          // ⑤ 瞬移残影（视频 10.8–11.3s）
    else if(r<0.62) setMood('think', 2600);
    else if(r<0.7) setMood('expect', 2600);
    else if(r<0.85) setMood('happy', 2600);
    else setMood('wave', 2200);
    petIdle();
  }, 4200 + Math.random()*4000);
}
function petWake(){
  clearTimeout(sleepTimer); clearTimeout(nudgeTimer);
  STATE.lastPetTouch = Date.now();
  if($('#pet').classList.contains('mood-sleep')) setMood('wave', 1800);
  // ⑥⑦ 久未互动：先挥手告别 + "bye" 气泡，再离场淡出，最后进入睡眠（1.2s 后自动复位，桌宠常驻不消失）
  sleepTimer = setTimeout(()=>{
    if(Date.now()-STATE.lastPetTouch > 55000){
      petBye();
      setTimeout(()=>setMood('sleep'), PET_ACT_MS.wave + PET_ACT_MS.exit + 1300);
    }
  }, 55000);
  // 长时间空闲（>28s 未互动）给一句轻柔提醒，不进睡眠
  nudgeTimer = setTimeout(()=>{ if(Date.now()-STATE.lastPetTouch > 28000 && !$('#pet').classList.contains('mood-sleep')) say(pickLine('idleLong')); }, 28000);
}
// 顶边悬挂（视频同款）：拖到屏幕上缘松手 → 倒挂摆动；否则吸附左右缘
const PEEK = 0.56;   // Photo Pet 贴边时保留 56% 在屏内；Boji 全身候选使用更完整的可见比例
function clamp(v,a,b){ return Math.max(a, Math.min(b, v)); }
function applyDock(){
  const pet = $('#pet'); if(!pet) return;
  const sr = $('#screen').getBoundingClientRect();
  const pw = pet.offsetWidth || 126, ph = pet.offsetHeight || 150;
  const dock0 = STATE.petDock || { edge:'right', off:0.62 };
  let dock = dock0;
  if(dock0.edge==='top'){
    const left = clamp((dock.off==null?0.5:dock.off)*sr.width - pw/2, 8, Math.max(8, sr.width-pw-8));
    pet.style.left = left+'px'; pet.style.top = (-ph*0.30)+'px'; pet.style.transform = 'none';
    pet.classList.remove('edge-l','edge-r','peek-more'); pet.classList.add('edge-t');
    return;
  }
  dock = (dock.edge==='left'||dock.edge==='right') ? dock : { edge:'right', off:0.62 };  // 旧的上/下停靠数据迁移为默认右缘
  const isRight = dock.edge==='right';
  const peek = STATE.petSkin==='boji' ? 0.78 : PEEK;
  const left = isRight ? sr.width - pw*peek : -pw*(1-peek);
  const top = clamp(dock.off*sr.height - ph/2, 56 - ph/2, sr.height - 104 - ph/2);
  pet.style.left = left+'px'; pet.style.top = top+'px'; pet.style.transform = 'none';
  pet.classList.remove('edge-l','edge-r','edge-t','peek-more');
  pet.classList.add(isRight?'edge-r':'edge-l');
}
// 拖拽结束后吸附：顶部 16% 以内 → 悬挂；否则吸最近侧缘
function dockToNearest(){
  const pet = $('#pet'); const sr = $('#screen').getBoundingClientRect(); const r = pet.getBoundingClientRect();
  const cx = r.left - sr.left + r.width/2, cy = r.top - sr.top + r.height/2;
  if(cy < sr.height*0.16){
    STATE.petDock = { edge:'top', off: clamp(cx/sr.width, 0.12, 0.88) }; save(); applyDock();
    petDashGhost();                                          // ⑤ 归位是瞬移，补一层残影（视频同款）
    say(pickLine('dangle'));
    return;
  }
  const edge = cx < sr.width/2 ? 'left' : 'right';
  const off = clamp(cy/sr.height, 0.1, 0.9);
  STATE.petDock = { edge, off }; save(); applyDock(); petDashGhost();
}
/* 视频同款小把戏：翻跟头 + 冒爱心 */
function petFlip(){
  const pet = $('#pet'); if(!pet || pet.classList.contains('flip')) return;
  pet.classList.add('flip'); setTimeout(()=>pet.classList.remove('flip'), 780);
}
function petHearts(n){
  const box = document.querySelector('#pet .pet-particles'); if(!box) return;
  for(let i=0;i<(n||6);i++){
    const h = document.createElement('i'); h.className = 'fly-heart'; h.textContent = '❤';
    h.style.left = (8+Math.random()*80)+'%';
    h.style.fontSize = (9+Math.random()*9)+'px';
    h.style.animationDelay = (Math.random()*0.55)+'s';
    box.appendChild(h); setTimeout(()=>h.remove(), 2400);
  }
}
/* ============================================================
   v1.1 桌宠「动作」增强 —— 借鉴 Shimeji-ee 的行为状态机
   参考 Shimeji-ee / Clover_Shimeji：用 behaviors.xml 定义
   idle / walk / drag / fall / sit / sleep，按权重随机触发、可被打断、结束回落 idle，
   并且**动作远多于表情**（正是本项目要的方向）。
   本项目桌宠停靠屏幕边缘，因此「行走」落地为**沿停靠边溜达**：位移 + 颠动 + 影子缩放，
   走一段再回来。刻意不做朝向镜像：.pet-body 的 transform 已被左右缘朝向占用，
   叠加会互相抵消（右缘镜像 × 朝向镜像 = 不翻），方向感改由位移方向表达。
   ============================================================ */
const PET_WALK_MS = 900;
let _walkTimers = [], _walking = false;
function petWalk(){
  const pet = $('#pet'); if(!pet || _walking) return;
  if(STATE.settings && STATE.settings.petWalk === false) return;   // 设置里可关
  if(document.hidden||prefersReducedMotion()) return;                // 后台或减少动态效果时不跑自动位移动画
  const sr = $('#screen').getBoundingClientRect(); if(!sr.width) return;
  const pw = pet.offsetWidth || 126, ph = pet.offsetHeight || 150;
  const dock = STATE.petDock || { edge:'right', off:0.62 };
  const along = dock.edge === 'top' ? 'x' : 'y';      // 顶边横向溜达；侧边纵向溜达
  const curX = parseFloat(pet.style.left) || 0, curY = parseFloat(pet.style.top) || 0;
  const dir = Math.random() < 0.5 ? -1 : 1;
  const dist = dir * (50 + Math.random() * 90);
  let tx = curX, ty = curY;
  if(along === 'x') tx = clamp(curX + dist, 4, Math.max(4, sr.width - pw - 4));
  else              ty = clamp(curY + dist, -ph*0.30, Math.max(-ph*0.30, sr.height - 132 - ph*0.2));
  _walking = true;
  pet.classList.add('pet-walking');
  pet.style.transition = 'left ' + PET_WALK_MS + 'ms linear, top ' + PET_WALK_MS + 'ms linear';
  pet.style.left = tx + 'px'; pet.style.top = ty + 'px';
  _walkTimers.push(setTimeout(()=>{
    pet.style.left = curX + 'px'; pet.style.top = curY + 'px';      // 走回原位
    _walkTimers.push(setTimeout(()=>{
      pet.classList.remove('pet-walking');
      pet.style.transition = 'none';
      _walking = false;
    }, PET_WALK_MS + 60));
  }, PET_WALK_MS + 120));
}
function petStopWalk(){
  _walkTimers.forEach(clearTimeout); _walkTimers = [];
  const pet = $('#pet'); if(!pet) return;
  pet.classList.remove('pet-walking'); pet.style.transition = 'none'; _walking = false;
  applyDock();
}
function pausePetMotion(){
  clearTimeout(idleTimer);idleTimer=null;
  clearTimeout(blinkTimer);blinkTimer=null;
  clearTimeout(petTimer);petTimer=null;
  clearTimeout(sleepTimer);sleepTimer=null;
  clearTimeout(nudgeTimer);nudgeTimer=null;
  petStopWalk();
  const bubble=$('#pet-bubble');if(bubble){clearTimeout(bubble._t);bubble._t=null;bubbleQueue=[];bubbleBusy=false;bubble.classList.remove('show');}
  const pet=$('#pet');if(pet)pet.classList.add('motion-paused');
}
function syncPetMotion(){
  const pet=$('#pet');
  if(document.hidden||prefersReducedMotion()){pausePetMotion();return;}
  if(pet)pet.classList.remove('motion-paused');
  scheduleBlink();petIdle();
}
/* 被抓 → 挣扎摆动；松手 → 落地回弹（对应 Shimeji 的 drag / fall） */
function petStruggle(on){ const pet = $('#pet'); if(!pet) return; pet.classList.toggle('pet-struggle', !!on); }
function petLand(){
  const pet = $('#pet'); if(!pet) return;
  pet.classList.add('pet-land'); setTimeout(()=>pet.classList.remove('pet-land'), 470);
}
/* ============================================================
   语音朗读 v1.2：情感韵律引擎（Web Speech API，端侧零依赖）
   —— 对照成熟方案后的取舍 ——
   · W3C Web Speech API：一个 utterance 只能带一组 rate/pitch/volume，且没有 SSML；
     所以要做出「有情绪、有个性」，只能靠「按标点切段 → 每段独立韵律 → 段间停顿」来模拟。
   · andresayac/ssml-builder / AACTools/js-tts-wrapper：用 <prosody rate/pitch> + <break>
     表达情绪，表达力更强，但全部依赖云端引擎（Azure / Google / Polly）与密钥，
     与本项目「离线优先、数据不出本机」冲突，故未接入；主方案走本地韵律引擎。
     （代价要如实说明：端侧引擎的「情感」只能到「语气起伏」这一层，
       达不到云端神经语音的细腻度。）
   —— 生命周期（本次硬性要求）——
   · 只在桌宠主界面发声；进入任何其它面板/页面立即 stop 并释放资源；
   · 回到主界面后，若刚才被中断，会把没说完的部分接着说完。
   ============================================================ */
const VOICE_MOOD = {
  happy:  { rate:1.14, pitch:1.24, vol:1.00 },
  cheer:  { rate:1.28, pitch:1.36, vol:1.00 },
  proud:  { rate:1.08, pitch:1.18, vol:1.00 },
  wave:   { rate:1.16, pitch:1.24, vol:0.98 },
  expect: { rate:1.12, pitch:1.32, vol:0.96 },
  think:  { rate:0.94, pitch:1.02, vol:0.92 },
  sad:    { rate:0.84, pitch:0.87, vol:0.86 },
  sleep:  { rate:0.78, pitch:0.85, vol:0.72 }
};
// 音色偏好：优先中文女声（Boji的设定是元气女教练），逐级回落
const VOICE_PREF = [/tingting/i, /meijia/i, /yaoyao/i, /huihui/i, /xiaoxiao/i, /yunxi/i, /female/i, /女/i, /zh/i];
function vc(v, a, b){ v = +v; if(!isFinite(v)) return a; return v < a ? a : (v > b ? b : v); }
function voicePick(){
  try{
    const vs = (window.speechSynthesis && window.speechSynthesis.getVoices) ? window.speechSynthesis.getVoices() : [];
    if(!vs || !vs.length) return null;
    const zh = vs.filter(v => /^zh|cmn|chinese|中文/i.test(String(v.lang) + ' ' + String(v.name)));
    const pool = zh.length ? zh : vs;
    for(const re of VOICE_PREF){ for(const v of pool){ if(re.test(String(v.name)) || re.test(String(v.voiceURI))) return v; } }
    return pool.find(v => v.default) || pool[0];
  }catch(_){ return null; }
}
/* 按标点切段并逐段定韵律：等价于 SSML 的 <prosody> + <break> */
function voiceSegments(text, base){
  const raw = String(text == null ? '' : text).slice(0, 120).trim();
  if(!raw) return [];
  const parts = raw.match(/[^。！？!?；;，,、…]+[。！？!?；;，,、…]?/g) || [raw];
  const out = [];
  parts.slice(0, 6).forEach(p => {
    const t = String(p || '').trim(); if(!t) return;
    const last = t.charAt(t.length - 1);
    let r = base.rate, pi = base.pitch, pause = 90;
    if(/[！!]/.test(last)){ r *= 1.12; pi *= 1.18; pause = 210; }        // 感叹：更亮更冲
    else if(/[？?]/.test(last)){ pi *= 1.30; pause = 230; }               // 疑问：句尾上扬
    else if(/[。]/.test(last)){ pause = 190; }                            // 陈述：正常收尾
    else if(/[…]/.test(last)){ r *= 0.90; pi *= 0.96; pause = 340; }      // 省略：放慢留白
    else if(/[，,、；;]/.test(last)){ pause = 170; }
    out.push({ t, rate: vc(r, 0.6, 1.9), pitch: vc(pi, 0.5, 1.95), pause });
  });
  return out.length ? out : [{ t: raw, rate: base.rate, pitch: base.pitch, pause: 0 }];
}
const VOICE = { seq:0, speaking:false, pending:'', leftAt:0, lastErr:'' };
function voiceSupported(){ try{ return !!(window.speechSynthesis && window.SpeechSynthesisUtterance); }catch(_){ return false; } }
/* 是否处于桌宠主界面：无面板打开且页面可见 */
function voiceOnHome(){
  try{
    if(document.hidden) return false;
    const ids = ['module', 'assistant'];
    for(const id of ids){ const el = document.getElementById(id); if(el && el.classList.contains('open')) return false; }
    return true;
  }catch(_){ return true; }
}
/* 停止并释放：cancel + 作废序号 + 记录未说完的部分 */
function stopVoice(reason){
  try{
    VOICE.seq++;                                   // 作废正在进行的朗读序列
    if(voiceSupported()){ window.speechSynthesis.cancel(); }
    if(VOICE.speaking && reason === 'leave') VOICE.leftAt = Date.now();
  }catch(_){}
  VOICE.speaking = false;
}
/* 切页/回桌面时的统一入口 */
function voiceSync(){
  if(!voiceOnHome()){ stopVoice('leave'); return false; }
  if(VOICE.pending && (Date.now() - VOICE.leftAt) < 60000){
    const t = VOICE.pending; VOICE.pending = '';   // 回到桌面接着说完
    setTimeout(()=>petSpeak(t), 420);
  }
  return true;
}
function voicePause(){ try{ if(voiceSupported() && VOICE.speaking) window.speechSynthesis.pause(); }catch(_){} }
function voiceResume(){ try{ if(voiceSupported() && window.speechSynthesis.paused) window.speechSynthesis.resume(); }catch(_){} }
/* 朗读主入口：返回 true 表示真的发声（浏览器不支持 / 不在主界面 / 未开启 → false） */
function petSpeak(text, opt){
  try{
    opt = opt || {};
    if(typeof window === 'undefined') return false;
    if(!voiceSupported()) return false;
    if(!(STATE.settings && STATE.settings.petVoice)) return false;
    if(!voiceOnHome()){ VOICE.pending = String(text || '').slice(0, 120); VOICE.leftAt = Date.now(); return false; }
    const raw = String(text == null ? '' : text).slice(0, 120).trim();
    if(!raw) return false;
    const mood = opt.mood || STATE.petMood || 'happy';
    const base = VOICE_MOOD[mood] || VOICE_MOOD.happy;
    const segs = voiceSegments(raw, base);
    if(!segs.length) return false;
    const synth = window.speechSynthesis;
    const voice = voicePick();
    const my = ++VOICE.seq;
    VOICE.speaking = true;
    try{ synth.cancel(); }catch(_){}
    let i = 0;
    const next = () => {
      if(my !== VOICE.seq) return;                        // 已被 stopVoice 作废
      if(i >= segs.length){ VOICE.speaking = false; return; }
      const s = segs[i++];
      let u;
      try{ u = new window.SpeechSynthesisUtterance(s.t); }catch(_){ VOICE.speaking = false; return; }
      u.lang = 'zh-CN'; u.rate = s.rate; u.pitch = s.pitch; u.volume = base.vol;
      if(voice){ try{ u.voice = voice; }catch(_){} }
      u.onend = () => { if(my !== VOICE.seq) return; setTimeout(next, s.pause); };
      u.onerror = () => { VOICE.lastErr = 'tts-error'; VOICE.speaking = false; };
      try{ synth.speak(u); }catch(_){ VOICE.speaking = false; }
    };
    next();
    return true;
  }catch(_){ return false; }
}
/* 照片做桌宠：上传照片 → 圆形抠图当脸，叠一层卡通眼嘴（贴纸式桌宠）。
   实事求是：端侧没有生成式模型，做不到「照片转二次元」；这里做的是
   「照片脸 + 自绘表情」的合成，效果可预期、无幻觉。 */
/* 取景参数：缩放 z + 水平/垂直偏移（用户可调，保证脸在圆里居中、比例协调） */
function photoFit(){
  const o = (STATE.settings && STATE.settings.petPhotoFit) || {};
  const z  = (+o.z  > 0.5 && +o.z  <= 3)  ? +o.z  : 1;
  const dx = isFinite(+o.dx) ? Math.max(-45, Math.min(45, +o.dx)) : 0;
  const dy = isFinite(+o.dy) ? Math.max(-45, Math.min(45, +o.dy)) : 0;
  return { z, dx, dy };
}
function photoPetSVG(mood, photo){
  const f = PET_FACE[mood] || PET_FACE.happy, T = PET_THEME;
  const src = (typeof photo === 'string' && photo.slice(0,5) === 'data:') ? photo : '';
  const fit = photoFit();
  // 表情模式：natura（默认，保留照片本人的五官，绝不叠假眼睛——这正是此前「表情异常」的根因）
  //          ／sticker（叠加卡通五官，可在设置里手动开启）
  const sticker = !!(STATE.settings && STATE.settings.petPhotoFx === 'sticker');
  const CX = 60, CY = 54, R = 44;
  const half = 48 * fit.z;
  const ix = (CX - half + fit.dx).toFixed(1), iy = (CY - half + fit.dy).toFixed(1),
        iw = (half * 2).toFixed(1), ih = (half * 2).toFixed(1);

  const face = src
    ? `<g clip-path="url(#phClip)">
         <image href="${src}" x="${ix}" y="${iy}" width="${iw}" height="${ih}"
                preserveAspectRatio="xMidYMid slice" image-rendering="auto" decoding="sync"/>
         <circle cx="${CX}" cy="${CY}" r="${R}" fill="url(#phVig)"/>
       </g>`
    : `<circle cx="${CX}" cy="${CY}" r="${R}" fill="url(#phSkin)"/>`;

  // 自然模式：靠腮红 / 睡意薄纱传达情绪，不覆盖照片本人的五官
  let expr = '';
  if(sticker){
    // 自绘五官按 0.82 缩放并重新定位到照片人脸的常规比例（眼≈0.45 头高、嘴≈0.72）
    const sc = (ax, ay, dy) => `translate(0,${dy}) translate(${ax},${ay}) scale(0.82) translate(${-ax},${-ay})`;
    expr = `<g transform="${sc(60, 63, -13)}">${petEye(f.eye, 45, 'L')}${petEye(f.eye, 75, 'R')}</g>
            <g transform="${sc(60, 77.4, -4)}">${petMouth(f.mouth)}</g>`;
  }else if(mood === 'sleep'){
    expr = `<g clip-path="url(#phClip)"><rect x="16" y="10" width="88" height="88" fill="#3a2f52" opacity=".34"/></g>
            <text x="80" y="34" font-size="13" font-weight="700" fill="#fff" opacity=".9">z</text>
            <text x="90" y="23" font-size="9" font-weight="700" fill="#fff" opacity=".72">z</text>`;
  }else if(f.blush){
    expr = `<ellipse cx="31" cy="66" rx="8" ry="4.4" fill="${T.blush}" opacity=".26"/>
            <ellipse cx="89" cy="66" rx="8" ry="4.4" fill="${T.blush}" opacity=".26"/>`;
  }
  // 底部小领结：给圆形头像一个「桌宠」身份锚点，视觉上也稳住头身比例
  const bow = `<g><ellipse cx="51" cy="102" rx="9.5" ry="6.8" fill="#8fd9bf" stroke="${T.trimB}" stroke-width="1.2"/>
    <ellipse cx="69" cy="102" rx="9.5" ry="6.8" fill="#8fd9bf" stroke="${T.trimB}" stroke-width="1.2"/>
    <circle cx="60" cy="102" r="3.6" fill="${T.gold}" stroke="${T.trimB}" stroke-width="1"/></g>`;

  // 关键修复：<svg> 必须带 width/height —— 之前只有 viewBox，浏览器按默认尺寸
  // 栅格化 dataURI，头像必糊。给到 240（实际显示 104，约 2.3×，高清屏也够用）。
  return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 120 120" width="240" height="240">
  <defs>
    <clipPath id="phClip"><circle cx="${CX}" cy="${CY}" r="${R}"/></clipPath>
    <linearGradient id="phSkin" x1="0" y1="0" x2="0" y2="1">
      <stop offset="0" stop-color="#fff6ee"/><stop offset="1" stop-color="#ffdfd2"/></linearGradient>
    <radialGradient id="phVig" cx="50%" cy="42%" r="62%">
      <stop offset="62%" stop-color="#000" stop-opacity="0"/>
      <stop offset="100%" stop-color="#2b1f3a" stop-opacity=".20"/></radialGradient>
  </defs>
  ${face}
  <circle cx="${CX}" cy="${CY}" r="${R}" fill="none" stroke="#fff" stroke-width="3.4" opacity=".92"/>
  <circle cx="${CX}" cy="${CY}" r="${R-1.6}" fill="none" stroke="#fff" stroke-width="1.1" opacity=".38"/>
  ${expr}
  ${bow}
</svg>`;
}
/* ============================================================
   按参考视频重制的动作序列（7 项）
   依据规格书逐帧结论：视频里只有「离散跳变」的坐标变化，腿部始终并拢，
   因此不存在行走 / 跳跃 / 任何连续位移动画 —— 这三类一律不实现。
   ① idle 待机呼吸 ② wave_hi 挥手 ③ bubble_hi 圆形气泡"hi"
   ④ crouch 蜷缩（视觉高度腰斩）⑤ dash_ghost 瞬移残影
   ⑥ wave_bye 挥手告别 + "bye" ⑦ exit 离场淡出
   ============================================================ */
const PET_ACT_MS = { idle:0, wave:1900, bubble:1800, crouch:1600, dash:500, exit:400 };
let _actTimer = null;
function petAct(name){
  const pet = $('#pet'); if(!pet) return;
  ['idle','wave','crouch','exit'].forEach(n=>pet.classList.remove('act-'+n));
  void pet.offsetWidth;                      // 强制重排，让同名动画能重新播放
  pet.classList.add('act-' + name);
  clearTimeout(_actTimer);
  if(name === 'idle') return;                // 待机是常驻循环，不自动清除
  _actTimer = setTimeout(()=>{
    pet.classList.remove('act-' + name);
    pet.classList.add('act-idle');           // 动作结束后回到待机
  }, PET_ACT_MS[name] || 0);
}
/* ③ 圆形气泡（视频里的 "hi" / "bye"）：延迟 0.2s 弹出 → 停留 1.8s → 淡出
   与打字机台词气泡互斥：正在说台词时排队等待，绝不中途打断
   （打断会让 typeBubble 的 done() 永不回调 → bubbleBusy 卡死 → 后续台词全部消失） */
let _roundTimer = null, _roundTry = 0;
function petRoundBubble(text, stayMs){
  const b = $('#pet-bubble'); if(!b) return;
  if(bubbleBusy && _roundTry < 8){ _roundTry++; setTimeout(()=>petRoundBubble(text, stayMs), 400); return; }
  _roundTry = 0;
  clearTimeout(_roundTimer); clearTimeout(b._t);
  b.classList.add('round'); b.classList.remove('show');
  b.innerHTML = '<b>' + esc(String(text == null ? '' : text).slice(0, 6)) + '</b>';
  _roundTimer = setTimeout(()=>{
    b.classList.add('show');
    _roundTimer = setTimeout(()=>{
      b.classList.remove('show');
      _roundTimer = setTimeout(()=>{ b.classList.remove('round'); b.innerHTML = ''; }, 360);
    }, stayMs || PET_ACT_MS.bubble);
  }, 200);
}
/* ⑤ 瞬移残影：2 层半透明副本，延迟 60 / 120ms 依次淡出 */
function petDashGhost(){
  const pet = $('#pet'); if(!pet) return;
  const img = $('#pet-img'); const src = img && img.src; if(!src) return;
  [['g1', 0], ['g2', 60]].forEach(pair=>{
    setTimeout(()=>{
      if(!document.body.contains(pet)) return;
      const im = document.createElement('img');
      im.className = 'pet-ghost ' + pair[0]; im.src = src; im.alt = '';
      pet.appendChild(im);
      setTimeout(()=>{ if(im.parentNode) im.remove(); }, 460);
    }, pair[1]);
  });
}
/* ②+③ 打招呼：挥手 + "hi" 气泡（进入 App / 从后台回来 / 轻点打招呼） */
function petGreet(){ petAct('wave'); petRoundBubble('hi'); }
/* ⑥+⑦ 告别：挥手 + "bye" 气泡 → 淡出，随后自动淡入复位（桌宠常驻，不会真的消失） */
function petBye(){
  petAct('wave'); petRoundBubble('bye');
  setTimeout(()=>{ petAct('exit'); }, PET_ACT_MS.wave);
  setTimeout(()=>{                                   // 离场后 1.2s 复位，避免桌宠消失不可恢复
    const pet = $('#pet'); if(!pet) return;
    pet.classList.remove('act-exit'); pet.classList.add('act-idle');
  }, PET_ACT_MS.wave + PET_ACT_MS.exit + 1200);
}
// 连点彩蛋：5 秒内轻点 ≥5 次 → 翻跟头 + 冒爱心 + 特殊反应（不影响轻点打开助手的默认行为）
let _tapTimes=[];
function petTapEgg(){
  const now = Date.now();
  _tapTimes = _tapTimes.filter(t=>now-t<5000); _tapTimes.push(now);
  if(_tapTimes.length>=5){
    _tapTimes=[];
    say(pickLine('tickle'));
    setMood('drag', 2200);
    petFlip(); petHearts(7);
  }
}
function initPet(){
  const pet = $('#pet'); if(!pet) return;
  if(STATE.petPos && !STATE.petDock){ STATE.petDock = { edge:'right', off:0.62 }; }  // 兼容旧版位置数据
  applyDock();
  setMood(STATE.petMood && LINES[STATE.petMood] ? STATE.petMood : 'happy');
  petWake();
  const petMotionQuery=window.matchMedia&&window.matchMedia('(prefers-reduced-motion: reduce)');
  if(petMotionQuery){
    if(petMotionQuery.addEventListener)petMotionQuery.addEventListener('change',syncPetMotion);
    else if(petMotionQuery.addListener)petMotionQuery.addListener(syncPetMotion);
  }
  syncPetMotion();
  petAct('idle');                                            // ① 待机呼吸（常驻）
  setTimeout(()=>{ if(!document.hidden) petGreet(); }, 900);  // ②+③ 开场挥手 + "hi" 气泡
  let sx,sy,ox,oy,dragged=false,pid=null;
  pet.addEventListener('pointerdown', e=>{
    pid=e.pointerId; pet.setPointerCapture(pid); pet.classList.add('dragging');
    pet.classList.remove('edge-l','edge-r','edge-t','edge-b','peek-more');  // 拎起时转正
    sx=e.clientX; sy=e.clientY; dragged=false;
    const r=pet.getBoundingClientRect(); const sr=$('#screen').getBoundingClientRect();
    ox=r.left-sr.left; oy=r.top-sr.top; e.preventDefault();
  });
  pet.addEventListener('pointermove', e=>{
    if(pid===null) return;
    const dx=e.clientX-sx, dy=e.clientY-sy;
    if(Math.abs(dx)>5||Math.abs(dy)>5){
      if(!dragged){ say(pickLine('drag')); petStopWalk(); petStruggle(true); }   // 抓起来 → 挣扎
      dragged=true;
    }
    const sr=$('#screen').getBoundingClientRect();
    let nl=ox+dx, nt=oy+dy;
    nl=Math.max(8, Math.min(sr.width-pet.offsetWidth-8, nl));
    nt=Math.max(50, Math.min(sr.height-pet.offsetHeight-90, nt));
    pet.style.left=nl+'px'; pet.style.top=nt+'px'; pet.style.transform='none';
  });
  const end=()=>{
    if(pid===null) return;
    pet.releasePointerCapture(pid); pid=null; pet.classList.remove('dragging');
    petStruggle(false);                                       // 松手 → 停止挣扎
    if(!dragged){ petTapEgg(); openAssistant(); }            // 轻点 = 展开助手对话（连点有彩蛋）
    else { dockToNearest(); petLand(); setMood('happy', 1600); }   // 拖拽 = 吸附最近边 + 落地回弹
    petWake();
  };
  pet.addEventListener('pointerup', end);
  pet.addEventListener('pointercancel', end);
  pet.addEventListener('keydown', e=>{ if(e.key==='Enter'||e.key===' '){ openAssistant(); }});
  // 鼠标悬停：向屏内多探头一点 + 轻脉冲 + 一句可爱台词（触屏无此事件）
  pet.addEventListener('pointerenter', e=>{
    if(e.pointerType!=='mouse') return;
    if(pet.classList.contains('dragging') || pet.classList.contains('mood-sleep')) return;
    pet.classList.add('hover-pulse','peek-more');
    setTimeout(()=>pet.classList.remove('hover-pulse','peek-more'), 620);
    say(pickLine('hover'));
  });
}

/* ============================================================
   P0 移动端返回键：层栈 + history 守卫
   ------------------------------------------------------------
   · 每打开一层（面板/弹窗）压入一条 history 记录，返回键回到上一层
   · 无层可退时才做“再按一次退出”，连按两次（2.2s 内）才真正离开
   · UI 上的 ✕ / 完成 通过 UI 关闭路径同步回退 history，避免堆栈错位
   ============================================================ */
const NAV = { stack:[], g:0, suppress:0, lastExit:0 };   // g = 由我们压入的 history 条数
const CLOSERS = {
  assistant:   ()=>{ const p=$('#assistant'); p.classList.remove('open'); p.setAttribute('aria-hidden','true'); },
  module:      ()=>{ const p=$('#module');    p.classList.remove('open'); p.setAttribute('aria-hidden','true'); },
  onboard:     ()=>{ const el=$('#onboard'); el.classList.remove('show'); el.setAttribute('aria-hidden','true');
    const target=$('#dock [aria-current="page"]')||$('#hc-go'); if(target&&target.focus)target.focus({preventScroll:true}); },
  'done-modal':()=>{ $('#done-modal').classList.remove('show'); },
  'food-sheet':()=>{ cancelFoodWork(); _fsPhotoFile=null; const s=$('#food-sheet'); s.classList.remove('show'); s.setAttribute('aria-hidden','true'); },
  // v1.2 视频弹层：关闭时务必清空 iframe/video，释放解码资源
  'video-pop': ()=>{ const p=$('#video-pop'); if(p) p.classList.remove('show');
    const st=$('#vpop-stage'); if(st) st.innerHTML=''; },
};
function navPush(tag){
  try { history.pushState({ boji:tag }, '', location.href); NAV.g++; return true; } catch(_){ return false; }
}
// 打开一层：先垫一条 shield（挡住真实的上一页），再压本层
function navOpen(id){
  if(NAV.g===0) navPush('shield');
  if(navPush('layer:'+id)) NAV.stack.push(id);
}
// UI 主动关闭（点 ✕ / 完成）：先关 DOM，再一次性回退对应层数
function navUIClose(id){
  const fn = CLOSERS[id]; if(fn) fn();
  const i = NAV.stack.lastIndexOf(id);
  if(i<0) return;
  const n = NAV.stack.length - i;          // 连同它之上的层一起退
  NAV.stack.length = i;
  NAV.suppress = n;
  try { history.go(-n); } catch(_){ NAV.suppress = 0; }
}
window.addEventListener('popstate', ()=>{
  NAV.g = Math.max(0, NAV.g - 1);
  if(NAV.suppress>0){ NAV.suppress--; return; }      // UI 关闭路径已处理，这里只做计数对齐
  const id = NAV.stack.pop();
  if(id){ const fn=CLOSERS[id]; if(fn) fn(); return; }
  navExitAttempt();
});
function navExitAttempt(){
  const now = Date.now();
  if(now - NAV.lastExit < 2200){          // 2.2s 内第二次 → 真退出
    NAV.lastExit = 0;
    try { window.close(); } catch(_){}
    setTimeout(()=>{ try { history.back(); } catch(_){} }, 80);
    return;
  }
  NAV.lastExit = now;
  toast('再按一次退出 Boji Companion (｡･ω･｡)');
  navPush('shield');                      // 补一层哨兵，防止下一次直接离开
}

/* ============================================================
   面板路由
   ============================================================ */
function openPanel(id){ const p=$('#'+id); p.classList.add('open'); p.setAttribute('aria-hidden','false'); navOpen(id); }
function closePanel(id){ navUIClose(id); voiceSync(); }   // 回到桌面：语音恢复（有未说完的会接着说）
function openAssistant(){ renderAssistant(); voiceSync(); if($('#assistant').classList.contains('open')){ return; } openPanel('assistant'); setMood('wave',1500); voiceSync(); }
function tabForModule(name){
  if(name==='diet'||name==='run'||name==='knowledge')return 'boji';
  if(name==='data')return 'progress';
  if(name==='profile')return 'profile';
  return ['today','training','boji','progress'].includes(name)?name:'today';
}
function updateDockState(tab){
  ACTIVE_TAB=tab;
  $$('#dock .dock-item[data-go]').forEach(button=>{
    const selected=button.dataset.go===tab;
    button.classList.toggle('active',selected);
    if(selected)button.setAttribute('aria-current','page');else button.removeAttribute('aria-current');
  });
}
function goModule(name){
  const transitionStarted=runtimeNow();
  const titles={training:['训练','学习动作，或进入今天的训练'],boji:['Boji','记录与陪伴都在这里'],progress:['进步','训练规律、力量记录与趋势'],data:['进步','训练规律、力量记录与趋势'],profile:['我的','档案与设置'],diet:['饮食记录','已确认的餐点与营养记录'],run:['跑步','记录路线、距离与时间'],knowledge:['训练知识','有来源边界的训练与营养问答']};
  if(name==='today'){
    updateDockState('today');ACTIVE_MODULE='today';renderHome();
    if($('#module').classList.contains('open'))closePanel('module');
    metricAfterPaint(RUNTIME_METRICS.pageTransitionMs,transitionStarted);
    return;
  }
  const title=titles[name]||titles.today;
  updateDockState(tabForModule(name));ACTIVE_MODULE=name;
  $('#mod-title').textContent=title[0]; $('#mod-sub').textContent=title[1];
  renderModule(name);
  voiceSync();                                          // 离开桌面：立即停语音并释放
  if($('#module').classList.contains('open')){metricAfterPaint(RUNTIME_METRICS.pageTransitionMs,transitionStarted);return;}   // 已打开：只重渲染，不重复压栈
  openPanel('module'); voiceSync();
  metricAfterPaint(RUNTIME_METRICS.pageTransitionMs,transitionStarted);
}

/* ============================================================
   桌面主屏
   ============================================================ */
function renderHome(){
  const now=new Date();
  $('#c-time').textContent = `${now.getHours()}:${String(now.getMinutes()).padStart(2,'0')}`;
  $('#sb-time').textContent = $('#c-time').textContent;
  $('#c-date').textContent = `${WEEKDAY[now.getDay()]} · ${now.getMonth()+1}月${now.getDate()}日`;
  const t=getDayType(now.getDay());
  const setsToday=COMPLETED_SETS_BY_DATE.get(todayKey())||0;
  $('#home-stats').innerHTML = `
    <div class="hs-pill">今日<b> ${dayTypeLabel(t)}</b></div>
    <div class="hs-pill">已完成<b> ${setsToday} 组</b></div>
    <div class="hs-pill">连续<b> ${streak()} 天</b></div>`;
  const ht = $('#home-today');
  if(t==='rest'){
    ht.innerHTML = `<div class="hc-head"><span class="hc-ic" aria-hidden="true">🌿</span><div><b>今天安排休息</b><span>按你当前选择的每周训练安排</span></div>
      <button class="hc-go" id="hc-go">查看训练 ›</button></div>
      <p class="hc-sub">今天的日历安排为休息日。你可以查看其他训练日，或按自己的状态安排轻松活动。</p>
      <p class="boji-note"><b>Boji：</b>你选择的${esc(planSetMeta().name)}方案把今天列为休息日。</p>
      <details class="today-why"><summary>为什么今天练这个？</summary><p>本周计划按你选择的训练方案和星期安排显示。今天对应休息日，训练记录不会因此增加。</p></details>`;
    $('#hc-go').onclick=()=>goModule('training');
  } else {
    const plan = PLANS[t];
    ht.innerHTML = `<div class="hc-head"><span class="hc-ic" aria-hidden="true">💪</span><div><b>${plan.name}</b><span>今天的训练安排</span></div>
      <button class="hc-go" id="hc-go">开始训练 ›</button></div>
      <p class="hc-sub">今天计划包含 ${plan.ex.length} 个动作；训练组会在保存后计入记录。</p>
      <div class="hc-chips">${plan.ex.slice(0,4).map(e=>`<span class="hc-chip">${e.name}</span>`).join('')}${plan.ex.length>4?`<span class="hc-chip more">+${plan.ex.length-4}</span>`:''}</div>
      <p class="boji-note"><b>Boji：</b>${esc(planSetMeta().name)}按星期安排今天的${esc(plan.name)}；进度只会在训练组保存后更新。</p>
      <details class="today-why"><summary>为什么今天练这个？</summary><p>这是你当前训练方案按星期安排的内容。系统没有根据缺少的档案或 AI 生成新计划。</p></details>`;
    $('#hc-go').onclick = ()=>goModule('training');
  }
}

/* ============================================================
   助手对话（Boji）
   ============================================================ */
/* 修复：旧正则把「证据标记 + 正文」整段一起替换掉，
   导致知识库里的「星级证据：NSCA 建议…」只剩一个「证据等级 B」徽章、正文消失（用户看到的是残缺回答）。
   改成只替换标记本身，正文原样保留。 */
function md(s){
  return esc(s)
    .replace(/\*\[([ABC])\]([^*]*)\*/g, (_, _lv, txt) => `<span class="ev">来源待核</span>${txt}`)
    .replace(/\*\*(.+?)\*\*/g, '<b>$1</b>');
}
function addMsg(role,text){
  const chat=$('#chat'); const node=el(`<div class="msg ${role}">${role==='bot'?`<img class="av" src="${coachAvatarSrc()}" alt="">`:''}${md(text)}</div>`);
  chat.appendChild(node); chat.scrollTop=chat.scrollHeight;
}
function renderAssistant(){
  const chat=$('#chat');
  if(chat.childElementCount===0){
    addMsg('bot',`你好呀，我是${coachName()}，你的专属增肌教练(｡･ω･｡)ﾉ\n训练、营养、恢复都可以问我——我只回答有科学出处的，没把握的我会直说，不瞎编。`);
  }
  const quick=$('#quick');
  quick.innerHTML='';
  ['今天练什么','蛋白质吃多少','卧推肩疼怎么办','什么时候加重量'].forEach(q=>{
    const b=el(`<button>${q}</button>`); b.onclick=()=>sendMsg(q); quick.appendChild(b);
  });
}
function sendMsg(text){
  text=(text||$('#chat-text').value).trim(); if(!text) return;
  $('#chat-text').value=''; addMsg('user',text); setMood('think',1400);
  setTimeout(()=>{ const r=bojiReply(text); addMsg('bot',r); setMood(/完成|棒|厉害|✓/.test(r)?'cheer':'happy',2600); }, 620);
}

